/* ================= 素材（画像・音声）：data URI として埋め込む ================= */
const ASSET={ivy:'data:image/webp;base64,',moss:'data:image/webp;base64,',stone:'data:image/webp;base64,',facade:'data:image/webp;base64,',roof:'data:image/webp;base64,',soil:'data:image/webp;base64,',soil2:'data:image/webp;base64,',waterfall:''};
U.uTexK={value:0};
function mkTex(src){
  const t=new T.Texture();t.wrapS=t.wrapT=T.RepeatWrapping;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;
  t.generateMipmaps=true;t.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());
  const im=new Image();im.onload=function(){t.image=im;t.needsUpdate=true;U.uTexK.value=Math.min(1,U.uTexK.value+0.15);};
  im.src=src;return t;
}
U.uIvy={value:mkTex(ASSET.ivy)};U.uMoss={value:mkTex(ASSET.moss)};U.uStone={value:mkTex(ASSET.stone)};U.uFacade={value:mkTex(ASSET.facade)};U.uRoof={value:mkTex(ASSET.roof)};U.uSoil={value:mkTex(ASSET.soil)};U.uSoil2={value:mkTex(ASSET.soil2)};
